    const postMoment = async () => {
      // 验证内容
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = newMoment.value.content;
      const textContent = tempDiv.textContent || tempDiv.innerText;
      if (!textContent.trim() && newMoment.value.media.length === 0) {
        ElMessage.warning('请输入有效内容或上传媒体文件');
        return;
      }
      posting.value = true;
      try {
        const formData = new FormData();
        formData.append('title', newMoment.value.title);
        formData.append('content', newMoment.value.content);
        newMoment.value.media.forEach((media, index) => {
          if (media.file) {
            formData.append(`media_${index}`, media.file);
          }
        });
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/moments`, formData, {
          headers: {
