      newMoment.value.media.push({
        type,
        url: URL.createObjectURL(file.raw),
        file: file.raw
      });
    };
    const beforeUpload = file => {
      const isMedia = file.type.startsWith('image/') || file.type.startsWith('video/');
      const isLt10M = file.size / 1024 / 1024 < 10;
      if (!isMedia) {
        ElMessage.error('只能上传图片或视频!');
        return false;
      }
      if (!isLt10M) {
        ElMessage.error('文件大小不能超过10MB!');
        return false;
      }
      return true;
    };
    const removeMedia = index => {
      newMoment.value.media.splice(index, 1);
    };
    const toggleLike = async moment => {
      try {
        const isLiked = moment.likes.some(like => like.user_id === currentUser.value.id);
        if (isLiked) {
          await axios.delete(`${API_CONFIG.BASE_URL}/article/moments/${moment.id}/likes`);
          moment.likes = moment.likes.filter(like => like.user_id !== currentUser.value.id);
        } else {
          const response = await axios.post(`${API_CONFIG.BASE_URL}/article/moments/${moment.id}/likes`);
          moment.likes.push(response.data);
        }
      } catch (error) {
        console.error('操作点赞失败:', error);
        ElMessage.error('操作失败');
      }
    };
    const toggleCommentInput = moment => {
      moment.showCommentInput = !moment.showCommentInput;
      if (moment.showCommentInput) {
        nextTick(() => {
          document.querySelector(`.moment-item[data-id="${moment.id}"] .comment-input input`).focus();
        });
      }
    };
    const postComment = async moment => {
