      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/moments/${moment.id}/comments`, {
          content: moment.newComment
        });
        moment.comments.push(response.data);
        moment.newComment = '';
        moment.showCommentInput = false;
        ElMessage.success('评论成功');
      } catch (error) {
        console.error('发表评论失败:', error);
        ElMessage.error('评论失败');
      }
    };
    const confirmDelete = momentId => {
      ElMessageBox.confirm('确定要删除这条动态吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        softDeleteMoment(momentId);
      }).catch(() => {});
    };
