      try {
        await axios.patch(`${API_CONFIG.BASE_URL}/article/moments/${momentId}`, {
          is_delete: -1
        });
        moments.value = moments.value.filter(moment => moment.id !== momentId);
        ElMessage.success('删除成功');
      } catch (error) {
        console.error('删除动态失败:', error);
        ElMessage.error('删除失败');
      }
    };
