          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          newMoment.value.content = '';
          newMoment.value.media = [];
          done();
        }).catch(() => {});
      } else {
        done();
      }
    };
